def get_max_occuring_char(str1):
    """Write a python function to find the maximum occurring character in a given string.

    Return the character that occurs most frequently in ``str1``.
    If several characters tie for the highest frequency, the one that
    first appears in ``str1`` is returned. Return ``None`` for an
    empty string.
    """
    if not str1:
        return None

    counts = {}
    for char in str1:
        counts[char] = counts.get(char, 0) + 1
    # dict preserves first-occurrence order, and max returns the first
    # maximal item it encounters, so ties resolve to the earliest char.
    return max(counts, key=counts.get)
